// cnt 트리: 리프 v에 값 v가 몇 개 있는지 저장 (값 1~8, 리프 순서대로)
int kth(int k, int l, int r, int rank) {   // rank번째로 작은 값
    if (l == r) return l;
    int m = (l + r) / 2;
    if (t[2 * k] >= rank) return kth(2 * k, l, m, rank);
    return kth(2 * k + 1, m + 1, r, rank - t[2 * k]);
}
// 호출: kth(1, 1, 8, rank)

